// CommonJS on purpose: Expo loads config plugins with require(), and an ES
// module there needs a recent Node, which EAS images do not promise.
const { copyFileSync, existsSync, readFileSync, writeFileSync } = require("node:fs");
const { basename, join } = require("node:path");
const { IOSConfig, WarningAggregator, withDangerousMod } = require("expo/config-plugins");

/**
 * Local StoreKit testing without App Store Connect.
 *
 * ios/ is regenerated by every prebuild, so the StoreKit configuration lives
 * in storekit/ and this plugin puts it back each time: it copies the file
 * into ios/ and writes a second shared scheme, "<App> StoreKit", whose Run
 * action uses it.
 *
 * A second scheme rather than the main one, because Xcode applies a scheme's
 * StoreKit file to every Run from that scheme: in the main scheme it would
 * quietly replace the App Store sandbox on a device as well. Choose
 * "Equina StoreKit" in Xcode and press Run (with Metro running). `expo
 * run:ios` launches through simctl and never applies a StoreKit file, so it
 * is unaffected either way.
 *
 * Purchases made this way reach RevenueCat only once its iOS app has the
 * certificate from Xcode (Editor > Save Public Certificate) and the app
 * runs with that iOS app's appl_ key.
 */
const withStoreKitConfiguration = (config, { file = "storekit/Equina.storekit" } = {}) =>
  withDangerousMod(config, [
    "ios",
    async (config) => {
      const { projectRoot, platformProjectRoot } = config.modRequest;
      const source = join(projectRoot, file);
      if (!existsSync(source)) {
        WarningAggregator.addWarningIOS("with-storekit-configuration", `${file} does not exist; no StoreKit scheme was written.`);
        return config;
      }
      const fileName = basename(file);
      copyFileSync(source, join(platformProjectRoot, fileName));

      const projectName = config.modRequest.projectName ?? IOSConfig.XcodeUtils.getProjectName(projectRoot);
      const schemes = join(platformProjectRoot, `${projectName}.xcodeproj`, "xcshareddata", "xcschemes");
      const mainScheme = join(schemes, `${projectName}.xcscheme`);
      if (!existsSync(mainScheme)) {
        WarningAggregator.addWarningIOS("with-storekit-configuration", `${mainScheme} does not exist; no StoreKit scheme was written.`);
        return config;
      }
      // Xcode resolves the path from the folder holding the open workspace,
      // ios/, which is where the file was just copied.
      writeFileSync(
        join(schemes, `${projectName} StoreKit.xcscheme`),
        withStoreKitReference(readFileSync(mainScheme, "utf8"), `../${fileName}`)
      );
      return config;
    }
  ]);

/** The scheme's Run action, pointed at one StoreKit file. Safe to apply twice. */
const withStoreKitReference = (scheme, identifier) => {
  const reference =
    `      <StoreKitConfigurationFileReference\n` +
    `         identifier = "${identifier}">\n` +
    `      </StoreKitConfigurationFileReference>\n`;
  return scheme.replace(/(<LaunchAction\b[\s\S]*?)(\s*<\/LaunchAction>)/, (_match, body, end) => {
    const clean = body.replace(/\s*<StoreKitConfigurationFileReference\b[\s\S]*?<\/StoreKitConfigurationFileReference>/g, "");
    const runnable = clean.lastIndexOf("</BuildableProductRunnable>");
    if (runnable === -1) return `${clean}\n${reference.trimEnd()}${end}`;
    const after = runnable + "</BuildableProductRunnable>".length;
    return `${clean.slice(0, after)}\n${reference.trimEnd()}${clean.slice(after)}${end}`;
  });
};

module.exports = withStoreKitConfiguration;
module.exports.withStoreKitReference = withStoreKitReference;
